#!/usr/bin/env Rscript
Sys.setenv(BMI_REPO_ROOT=normalizePath("."));source("R/analysis.R");source("tests/fixtures/bmi_curve_fixture.R")
config<-bmi_config();checks<-list()
check<-function(id,fun){err<-tryCatch({fun();NULL},error=function(e)e);checks[[id]]<<-data.frame(check_id=id,passed=is.null(err),detail=if(is.null(err))"passed"else conditionMessage(err));message(if(is.null(err))"PASS "else"FAIL ",id,if(!is.null(err))conditionMessage(err))}
near<-function(a,b)stopifnot(isTRUE(all.equal(a,b,tolerance=1e-8,check.attributes=FALSE)))
d<-make_bmi_curve_fixture(480,adverse=FALSE);d$bmi_evidence_state<-ifelse(is.na(d$bmi),"missing","valid")
check("empty_group",function(){z<-bmi_run_population_analysis(d[FALSE,],config,audit_only=TRUE);stopifnot(all(z$cohort_nodes$n[z$cohort_nodes$population_id %in% c("Q","C")]==0))})
check("truth_table",function(){z<-d[1:7,];z[bmi_rfs_fields]<-0L;z$OBESITY_rfs<-c(1,0,1,NA,1,NA,0);z$ABG_rfs<-c(0,1,1,1,NA,NA,0);z$VBG_rfs[4]<-NA;x<-bmi_classify_rfs(z);stopifnot(identical(x$rfs_group,c("obesity_only","primary","primary","primary","unresolved","unresolved","unresolved")),x$rfs_subgroup[7]=="all_zero_discrepancy")})
check("membership_not_outcome",function(){z<-d[1:3,];z[bmi_rfs_fields]<-0L;z$OBESITY_rfs<-1L;z$abg_pco2<-c(44,45,60);z$has_abg<-1L;x<-construct_cohort_and_memberships(z);stopifnot(all(x$data$rfs_group=="obesity_only"),identical(x$data$abg,c(0L,1L,1L)))})
check("metadata_index_invariance",function(){base<-construct_cohort_and_memberships(d);z<-d;z[bmi_rfs_fields]<-NA_real_;z$bmi_method<-NA_character_;other<-construct_cohort_and_memberships(z);stopifnot(identical(tri_encounter_key(base$members$Q),tri_encounter_key(other$members$Q)))})
check("metadata_conflict_does_not_drop_index",function(){z<-d[1:2,];z$bmi<-40;z$bmi_evidence_state<-"valid";z<-rbind(z,z[1,]);z$OBESITY_rfs[3]<-1-z$OBESITY_rfs[1];v<-validate_triangulation_input(z);stopifnot(nrow(v)==2,!any(v$.key_conflict),is.na(v$OBESITY_rfs[1]))})
check("current_measurement",function(){z<-d[1:4,];z$bmi_method<-c("current","prior","calculated","calculated");z$reported_date<-z$encounter_date;z$height_date<-z$weight_date<-z$encounter_date;z$height_date[4]<-z$encounter_date[4]-30;x<-bmi_classify_rfs(z);stopifnot(identical(x$current_bmi_verified,c(TRUE,FALSE,TRUE,FALSE)))})
check("unknown_lag",function(){z<-d[1:2,];z$reported_date[1]<-NA;x<-bmi_classify_rfs(z);stopifnot(is.na(x$bmi_lag_days[1]),x$bmi_lag_days[2]>=0)})
a<-bmi_run_analysis(d,config)
check("registry_configuration",function(){validate_analysis_bundle(a);stopifnot(setequal(a$model_registry$model_id,a$expected_models$model_id),nrow(a$model_registry)==2*nrow(bmi_model_registry("qualified"))+3*3)})
check("partition",function(){near(sum(a$rfs_summary$n),a$cohort_nodes$n[a$cohort_nodes$population_id=="combined::Q"]);stopifnot(all(a$rfs_summary$complete+a$rfs_summary$incomplete==a$rfs_summary$n))})
check("coverage_namespaced",function(){stopifnot(all(a$model_registry$model_id %in% a$coverage_index$item_id),all(a$cohort_nodes$population_id %in% a$coverage_index$item_id))})
check("no_combined_primary",function(){stopifnot(!any(grepl("^combined::",a$model_registry$model_id)))})
check("separate_bases",function(){b<-a$bmi_basis;stopifnot(length(unique(b$basis_id[b$analysis_population_id %in% c("primary","obesity_only")]))==2);near(b$knot[b$analysis_population_id=="primary"],b$knot[b$analysis_population_id=="primary_current"]);stopifnot(all(b$reference_id[b$analysis_population_id=="primary_current"]=="primary::C"))})
check("outcome_observed_reference",function(){for(id in a$model_registry$model_id){r<-a$model_registry[a$model_registry$model_id==id,];z<-a$probability_curves[a$probability_curves$model_id==id,];if(nrow(z))stopifnot(all(z$reference_id==r$training_population_id))}})
check("grid_support",function(){z<-a$probability_curves;z<-z[z$status=="estimated",];stopifnot(nrow(z)>0,all(c("within_training_bmi_range","local_n","locally_sparse","missing_local_factor_levels")%in%names(z)),!"supported"%in%names(z),any(z$locally_sparse))})
check("paired_decomposition",function(){for(i in which(a$policy_totals$status=="estimated")){t<-a$policy_totals[i,];z<-a$policy_contributions[a$policy_contributions$model_id==t$model_id,];near(sum(z$D),t$absolute_difference);near(t$PIF,1-t$p_shifted/t$p_observed)}})
check("unavailable_explicit",function(){stopifnot(all(a$prior_run_reconciliation$status=="not_assessed"),all(a$rfs_outcomes$evaluable+a$rfs_outcomes$unknown==a$rfs_outcomes$N))})
check("dictionary_and_privacy",function(){validate_analysis_bundle(a);stopifnot(all(c(bmi_metadata_fields,"bmi_lag_days")%in%a$variable_dictionary$variable_id),!any(vapply(a,function(x)any(vapply(x,inherits,logical(1),"Date")),logical(1))))})
check("pending_timing_wrapper",function(){z<-bmi_run_analysis(make_bmi_curve_fixture(36,with_index_day=FALSE),config);r<-z$model_registry[z$model_registry$window=="index_calendar_day",];stopifnot(all(r$status=="pending_source"),all(is.na(r$n_model)),!any(z$numerical_reconciliation$passed %in% FALSE))})
check("old_bundle_rejected",function(){p<-tempfile();dir.create(p);jsonlite::write_json(list(schema_version=5L,analysis_id="bmi_hypercapnia_observed_curve_audit_v2"),file.path(p,"bundle_manifest.json"));e<-tryCatch(bmi_read_bundle(p),error=function(e)e);stopifnot(inherits(e,"error"));unlink(p,recursive=TRUE)})
out<-file.path("artifacts/triangulation",paste0("rfs-tests-",format(Sys.time(),"%Y%m%dT%H%M%S"),"-",Sys.getpid()));dir.create(out,recursive=TRUE)
utils::write.csv(bmi_bind(checks),file.path(out,"automated-results.csv"),row.names=FALSE)
if(any(!bmi_bind(checks)$passed))stop("RFS checks failed; fresh receipt: ",out)
message("RFS checks passed; artificial data only: ",out)
